
#!/usr/bin/env bash
set -Eeuo pipefail

export AWS_PAGER=""
REGION="us-east-1"

die() {
  echo "FAIL: $*" >&2
  exit 1
}

[[ -f state.env ]] || die "state.env not found. Run setup first."
# state.env is generated by setup.sh and must remain private.
source state.env

: "${VPC_ID:?VPC_ID missing from state.env}"
: "${SUBNET_ID:?SUBNET_ID missing from state.env}"
: "${IGW_ID:?IGW_ID missing from state.env}"
: "${ROUTE_TABLE_ID:?ROUTE_TABLE_ID missing from state.env}"
: "${SG_ID:?SG_ID missing from state.env}"

echo "Checking VPC..."
VPC_STATE="$(aws ec2 describe-vpcs --region "$REGION" \
  --vpc-ids "$VPC_ID" --query 'Vpcs[0].State' --output text)"
[[ "$VPC_STATE" == "available" ]] || die "VPC state is $VPC_STATE"

echo "Checking subnet..."
SUBNET_STATE="$(aws ec2 describe-subnets --region "$REGION" \
  --subnet-ids "$SUBNET_ID" --query 'Subnets[0].State' --output text)"
[[ "$SUBNET_STATE" == "available" ]] || die "Subnet state is $SUBNET_STATE"

echo "Checking default internet route..."
DEFAULT_ROUTE="$(aws ec2 describe-route-tables --region "$REGION" \
  --route-table-ids "$ROUTE_TABLE_ID" \
  --query 'RouteTables[0].Routes[?DestinationCidrBlock==`0.0.0.0/0`].GatewayId | [0]' \
  --output text)"
[[ "$DEFAULT_ROUTE" == "$IGW_ID" ]] ||
  die "Default route does not point to the project's Internet Gateway."

echo "Checking HTTP ingress..."
HTTP_RULE="$(aws ec2 describe-security-groups --region "$REGION" \
  --group-ids "$SG_ID" \
  --query 'SecurityGroups[0].IpPermissions[?IpProtocol==`tcp` && FromPort==`80` && ToPort==`80`].FromPort | [0]' \
  --output text)"
[[ "$HTTP_RULE" == "80" ]] || die "HTTP ingress rule is missing."

echo "Checking that inbound SSH is absent..."
SSH_RULE="$(aws ec2 describe-security-groups --region "$REGION" \
  --group-ids "$SG_ID" \
  --query 'SecurityGroups[0].IpPermissions[?IpProtocol==`tcp` && FromPort==`22` && ToPort==`22`].FromPort | [0]' \
  --output text)"
[[ "$SSH_RULE" == "None" || -z "$SSH_RULE" ]] ||
  die "Inbound SSH rule found. Review the security group."

echo
echo "NETWORK VERIFICATION PASSED"
echo "VPC:         $VPC_ID"
echo "Subnet:      $SUBNET_ID"
echo "Internet GW: $IGW_ID"
echo "Route table: $ROUTE_TABLE_ID"
echo "Security SG: $SG_ID"
echo "No EC2 instance is checked at this stage."